<?php
declare(strict_types=1);
// Page: ?page=sync — included by index.php inside its try/catch, after the sign-in, CSRF and $page checks.
 $schema=current_schema(); $table=$_GET['table']??''; require_perm('copy_records'); if($_SERVER['REQUEST_METHOD']==='POST'){ $mode=$_POST['mode']??'merge'; $to=$_POST['to_schema']??''; assert_copy_schemas((string)($_POST['from_schema']??''),(string)$to,true); if(!table_exists((string)$_POST['from_schema'],$table)||!table_exists($to,$table)) throw new RuntimeException('Table must exist in both schemas.'); if($mode==='sync' && is_protected_schema($to)) throw new RuntimeException('Full-table sync cannot target '.$to.'. Choose Merge instead.'); $action=$mode==='sync'?'sync_table':'merge_table'; $token=make_confirmation($action,['from'=>$_POST['from_schema'],'to'=>$to,'table'=>$table,'return_to'=>'?page=table&table='.urlencode($table)]); redirect('?page=confirm&token='.$token); } layout_start('Copy / Sync Table'); ?><div class="cardx"><h3>Copy full table data</h3><div class="alert alert-info"><b>Merge</b> upserts by primary key and never deletes existing rows — safe for HeraProduction. <b>Full sync</b> truncates the destination table first and can only target HeraTesting.</div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="row g-3"><div class="col-md-3"><label>Mode</label><select name="mode" class="form-select"><option value="merge">Merge (safe, upsert)</option><option value="sync">Full sync (truncate + reload, HeraTesting only)</option></select></div><div class="col-md-3"><label>From</label><select name="from_schema" class="form-select"><?php foreach(user_schemas() as $s):?><option><?=e($s)?></option><?php endforeach;?></select></div><div class="col-md-3"><label>To</label><select name="to_schema" class="form-select"><?php foreach(array_reverse(user_schemas()) as $s):?><option><?=e($s)?></option><?php endforeach;?></select></div><div class="col-md-3 d-flex align-items-end"><button class="btn btn-danger w-100">Preview & Confirm</button></div></div></form></div><?php layout_end(); exit;
